// ==========================================
// 2. AQS Helpers & Theme Colors
// ==========================================
export function normalizeAQS(rawAqs) {
  if (!rawAqs) return "";
  return rawAqs.toString().replace(/[^0-9]/g, "").padStart(9, "0");
}

export function formatAQSDisplay(rawAqs) {
  const norm = normalizeAQS(rawAqs);
  if (norm.length !== 9) return rawAqs || "";
  return `${norm.slice(0, 2)}-${norm.slice(2, 5)}-${norm.slice(5)}`;
}

function getEChartsThemeColors() {
  const style = getComputedStyle(document.documentElement);
  return {
    textColor: style.getPropertyValue("--text-main").trim() || "#f8fafc",
    textStrong: style.getPropertyValue("--text-strong").trim() || "#ffffff",
    bgColor: style.getPropertyValue("--color-bg").trim() || "#0f172a",
    borderColor: style.getPropertyValue("--border-main").trim() || "rgba(255,255,255,0.15)",
    cardShadow: style.getPropertyValue("--card-shadow").trim() || "#8abfff"
  };
}

