export function generateDashboardContext(userInput = "") {
  const contextLines = [];

  // 0. Current Real-world Time & Timezone (Local)
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  const localToday = `${year}-${month}-${day}`;

  const timeZoneName = Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";
  const tzMatch = now.toTimeString().match(/\((.+)\)$/);
  const tzAbbr = tzMatch ? tzMatch[1] : "";
  const offsetMin = -now.getTimezoneOffset();
  const offsetHours = offsetMin / 60;
  const offsetStr = `UTC${offsetHours >= 0 ? "+" : ""}${offsetHours}`;

  contextLines.push(`User Local Time: ${now.toLocaleString()}`);
  contextLines.push(`User Timezone: ${timeZoneName} (${tzAbbr ? tzAbbr + ", " : ""}${offsetStr})`);
  contextLines.push(`Today's Local Date: ${localToday}`);

  // 1. Date & Time (Dashboard View Date & Time)
  const datePicker = document.getElementById("datePicker");
  const activeDate = datePicker?.value || copilotState.persistedDate || localToday;
  contextLines.push(`View Date (Map Active Date): ${activeDate}`);

  const timePicker = document.getElementById("timePicker");
  const timezoneLabel = document.getElementById("timezoneLabel");
  if (timePicker && timePicker.value) {
    const tzText = timezoneLabel ? timezoneLabel.textContent.trim() : (tzAbbr || "Local");
    contextLines.push(`Active Map Time: ${timePicker.value}:00 ${tzText}`);
  }

  // 2. Published Dataset Model
  const dsSelect = document.getElementById("MapDataSelect");
  if (dsSelect) {
    const val = dsSelect.value;
    const text = dsSelect.options[dsSelect.selectedIndex]?.text || "Unknown";
    contextLines.push(`Active Model: ID="${val}", Label="${text}"`);

    const yearNum = parseInt(activeDate.split("-")[0], 10);
    if (yearNum >= 2019 && yearNum <= 2024) {
      if (val === "gam-v2-pred") {
        contextLines.push(`Effective Model (Historical Auto-Correction): ID="gam-v2"`);
      } else if (val === "pm-cbsa-pred") {
        contextLines.push(`Effective Model (Historical Auto-Correction): ID="pm-cbsa"`);
      }
    }
  }

  // 3. Active & Available Layers in UI
  const activeLayers = [];
  const availableLayers = [];
  document.querySelectorAll(".accordion-page input[type='checkbox']").forEach(cb => {
    if (cb.id.startsWith("layer-")) {
      const isHidden = cb.closest("[style*='display: none'], [style*='display:none']");
      if (!isHidden) {
        const labelText = (cb.parentElement ? cb.parentElement.textContent : "").replace(/\s+/g, " ").trim() || cb.id;
        availableLayers.push(`${cb.id}("${labelText}")`);
        if (cb.checked) {
          activeLayers.push(`${cb.id}("${labelText}")`);
        }
      }
    }
  });

  contextLines.push(`Available Layers in UI: [${availableLayers.join(", ")}]`);
  contextLines.push(`Active Layers: ${activeLayers.length > 0 ? activeLayers.join(", ") : "None"}`);

  // 4. In-Memory Loaded GeoJSON Datasets
  if (loadedGeoJSON && typeof loadedGeoJSON === "object") {
    const loadedList = [];
    for (const [key, data] of Object.entries(loadedGeoJSON)) {
      if (data && data.features && data.features.length > 0) {
        loadedList.push(`${key} (${data.features.length} sites)`);
      }
    }
    if (loadedList.length > 0) {
      contextLines.push(`Loaded Map GeoJSON Data: [${loadedList.join(", ")}]`);
    }
  }

  // 5. Target Site AQS
  const activeAqs = copilotState.persistedAqs || "49-035-3006";
  contextLines.push(`Target Selected Site (AQS): ${formatAQSDisplay(activeAqs)} (${normalizeAQS(activeAqs)})`);

  return contextLines.join("\n");
}

export function showAiCopilotModal() {
  if (!auth.currentUser) {
    utils.showAuthOverlay();
    return;
  }

  let modal = document.getElementById("AiCopilotModalOverlay");
  if (!modal) {
    createAiCopilotDOM();
    modal = document.getElementById("AiCopilotModalOverlay");
  }
  modal.style.display = "flex";

  // Real-time API Key Warning Management
  const existingWarning = document.getElementById("AiCopilotApiKeyWarning");
  const hasApiKey = !!localStorage.getItem("smokelyze_gemini_key");

  if (hasApiKey) {
    if (existingWarning) existingWarning.remove();
  } else if (!existingWarning) {
    const chatList = document.getElementById("AiCopilotChatList");
    if (chatList) {
      chatList.insertAdjacentHTML("beforeend", `
        <div id="AiCopilotApiKeyWarning" style="background: rgba(250, 200, 88, 0.1); border: 0.1rem solid var(--card-shadow); padding: 1rem; border-radius: 0.6rem; font-size: 1.2rem; color: var(--text-main);">
          API Key is not set yet. Please register your Gemini API key in <strong>[Profiles] &gt; [Settings] &gt; [Google Gemini API]</strong> to activate all real-time features.
        </div>
      `);
      chatList.scrollTop = chatList.scrollHeight;
    }
  }

  if (copilotState.activeChart) {
    setTimeout(() => copilotState.activeChart.resize(), 100);
  }
}

export function hideAiCopilotModal() {
  const modal = document.getElementById("AiCopilotModalOverlay");
  if (modal) modal.style.display = "none";
  document.getElementById("AiCopilotModalContainer")?.classList.remove("is-mobile-canvas-view");
}

export function hideCopilotCanvas() {
  const container = document.getElementById("AiCopilotModalContainer");
  if (container) {
    container.classList.remove("is-mobile-canvas-view");
    container.classList.add("is-collapsed");
  }
}

export function showCopilotCanvas() {
  const container = document.getElementById("AiCopilotModalContainer");
  if (!container) return;

  if (window.innerWidth <= 1024) {
    container.classList.add("is-mobile-canvas-view");
  } else if (container.classList.contains("is-collapsed")) {
    container.classList.remove("is-collapsed");
  }

  if (copilotState.activeChart) {
    setTimeout(() => copilotState.activeChart.resize(), 50);
  }
}

